const LOCAL_TEMPLATES=[{"title": "快速 IO", "tags": "io C++17", "notes": "适用于标准输入输出；关闭同步后不要混用 scanf/printf。\n来源：本项目原创整理；C++ 片段需自行包含对应标准头文件（断言需 <cassert>）并使用 std 命名空间。", "code": "#include <bits/stdc++.h>\nusing namespace std;\nint main() {\n    ios::sync_with_stdio(false); cin.tie(nullptr);\n    // 在这里读取输入并求解。\n    return 0;\n}", "language": "cpp"}, {"title": "并查集", "tags": "DSU 连通性 图论", "notes": "下标 0..n-1；按大小合并与路径压缩，摊还近似 O(1)。\n来源：本项目原创整理；C++ 片段需自行包含对应标准头文件（断言需 <cassert>）并使用 std 命名空间。", "code": "struct DSU {\n    vector<int> p, sz;\n    explicit DSU(int n): p(n), sz(n,1) { iota(p.begin(),p.end(),0); }\n    int find(int x) { return p[x]==x ? x : p[x]=find(p[x]); }\n    bool unite(int a,int b) {\n        a=find(a); b=find(b); if(a==b)return false;\n        if(sz[a]<sz[b])swap(a,b);\n        p[b]=a; sz[a]+=sz[b]; return true;\n    }\n};", "language": "cpp"}, {"title": "Dijkstra 最短路", "tags": "图论 堆 最短路", "notes": "仅用于非负边权；下标 0..n-1，O((n+m) log n)。INF 为 2^62，需保证真实距离更小。\n来源：本项目原创整理；C++ 片段需自行包含对应标准头文件（断言需 <cassert>）并使用 std 命名空间。", "code": "using ll = long long;\nconst ll INF = (1LL<<62);\nvector<ll> dijkstra(const vector<vector<pair<int,ll>>>& g, int s) {\n    vector<ll> d(g.size(), INF);\n    priority_queue<pair<ll,int>,vector<pair<ll,int>>,greater<pair<ll,int>>> q;\n    d[s]=0; q.push({0,s});\n    while(!q.empty()) {\n        auto [dist,u]=q.top(); q.pop(); if(dist!=d[u])continue;\n        for(auto [v,w]:g[u]) {\n            assert(w>=0);\n            if(w>=INF || dist>INF-w)continue;\n            if(dist+w<d[v]) { d[v]=dist+w; q.push({d[v],v}); }\n        }\n    }\n    return d;\n}", "language": "cpp"}, {"title": "BFS 无权最短路", "tags": "图论 BFS 队列", "notes": "下标 0..n-1；所有边权相同。距离 -1 表示不可达，O(n+m)。\n来源：本项目原创整理；C++ 片段需自行包含对应标准头文件（断言需 <cassert>）并使用 std 命名空间。", "code": "vector<int> bfs(const vector<vector<int>>& g,int s) {\n    vector<int> d(g.size(),-1); queue<int> q; d[s]=0; q.push(s);\n    while(!q.empty()) {\n        int u=q.front(); q.pop();\n        for(int v:g[u])if(d[v]==-1){d[v]=d[u]+1;q.push(v);}\n    }\n    return d;\n}", "language": "cpp"}, {"title": "树状数组", "tags": "Fenwick 前缀和 数据结构", "notes": "1..n 下标；add 的下标必须 >=1，区间和 sum(r)-sum(l-1)，注意总和溢出。\n来源：本项目原创整理；C++ 片段需自行包含对应标准头文件（断言需 <cassert>）并使用 std 命名空间。", "code": "struct Fenwick {\n    int n; vector<long long> t;\n    explicit Fenwick(int n):n(n),t(n+1){}\n    void add(int x,long long v){assert(x>=1&&x<=n);for(;x<=n;x+=x&-x)t[x]+=v;}\n    long long sum(int x){assert(x>=0&&x<=n);long long s=0;for(;x;x-=x&-x)s+=t[x];return s;}\n};", "language": "cpp"}, {"title": "模快速幂", "tags": "数论 二进制 快速幂", "notes": "指数非负、模数正数；GCC/Clang 的 __int128 避免 long long 模乘溢出。\n来源：本项目原创整理；C++ 片段需自行包含对应标准头文件（断言需 <cassert>）并使用 std 命名空间。", "code": "long long modpow(long long a, unsigned long long e, long long mod) {\n    assert(mod>0); a%=mod;if(a<0)a+=mod;\n    long long r=1%mod;\n    for(;e;e>>=1,a=(__int128)a*a%mod)if(e&1)r=(__int128)r*a%mod;\n    return r;\n}", "language": "cpp"}, {"title": "半开区间二分", "tags": "二分 lower_bound 边界", "notes": "predicate 需满足先 false 后 true；返回第一个 true，全部 false 返回 r。输入区间 [l,r)。\n来源：本项目原创整理；C++ 片段需自行包含对应标准头文件（断言需 <cassert>）并使用 std 命名空间。", "code": "int first_true(int l,int r, const function<bool(int)>& predicate) {\n    while(l<r){int mid=l+(static_cast<long long>(r)-l)/2;if(predicate(mid))r=mid;else l=mid+1;}\n    return l;\n}", "language": "cpp"}, {"title": "Python 对拍脚本", "tags": "对拍 随机 测试", "notes": "来源：本项目原创整理。仅供电脑端运行；在本机准备 gen.py、solution.py 和 brute.py，逐次生成输入，对比输出，失败保存 case.txt。不要运行不可信程序。", "language": "python", "code": "import subprocess\nfrom pathlib import Path\nimport sys\n\ndef run(name, data=None):\n    return subprocess.run([sys.executable, name], input=data,\n                          stdout=subprocess.PIPE, check=True, timeout=5).stdout\n\nfor test in range(1000):\n    data = run(\"gen.py\")\n    Path(\"case.txt\").write_bytes(data)\n    actual, expected = run(\"solution.py\", data), run(\"brute.py\", data)\n    if actual.split() != expected.split():\n        print(\"Mismatch\", test, \"saved in case.txt\")\n        break\nelse:\n    print(\"All 1000 cases agree\")\n"}];
